-- Datos que toda instalacion necesita despues de cargar Decatron.Data/Schema/baseline.sql: el tenant #1 (el bot propio), el catalogo de capacidades
-- y el plan interno del #1 (todo sin tope). Los planes comerciales (sandbox, de pago) y sus precios NO van aqui: son configuracion de quien opera
-- la plataforma. Para abrir el registro de compradores hace falta al menos el plan con key 'sandbox' (TenantProvisioner lo exige).
-- Idempotente. Aplicar como el dueno de la base (decatron_user): las politicas RLS no filtran al dueno.
BEGIN;
INSERT INTO tenants (id, slug, name, status, credentials_mode) VALUES (1, 'decatron', 'Decatron', 'active', 'legacy') ON CONFLICT DO NOTHING;
SELECT setval('tenants_id_seq', GREATEST((SELECT max(id) FROM tenants), 1));

INSERT INTO capabilities SELECT * FROM json_populate_recordset(null::capabilities, $j$[{"key": "quota.channels", "kind": "quota", "unit": "canales", "group_key": "cuotas", "default_value": 1, "meter": "gauge", "period": null, "description": "Canales conectados al tenant", "active": true, "sort": 10}, {"key": "quota.admins", "kind": "quota", "unit": "personas", "group_key": "cuotas", "default_value": 1, "meter": "gauge", "period": null, "description": "Administradores del tenant", "active": true, "sort": 20}, {"key": "quota.chat_messages_month", "kind": "quota", "unit": "mensajes", "group_key": "cuotas", "default_value": null, "meter": "counter", "period": "month", "description": "Mensajes de chat procesados por mes (avisa al 80 %, no corta el chat)", "active": true, "sort": 30}, {"key": "quota.commands", "kind": "quota", "unit": "comandos", "group_key": "cuotas", "default_value": null, "meter": "gauge", "period": null, "description": "Comandos personalizados", "active": true, "sort": 40}, {"key": "quota.timers", "kind": "quota", "unit": "timers", "group_key": "cuotas", "default_value": null, "meter": "gauge", "period": null, "description": "Timers de mensajes", "active": true, "sort": 50}, {"key": "quota.storage_mb", "kind": "quota", "unit": "MB", "group_key": "cuotas", "default_value": null, "meter": "gauge", "period": null, "description": "Almacenamiento de archivos (clips, sonidos, imagenes)", "active": true, "sort": 60}, {"key": "quota.emails_month", "kind": "quota", "unit": "correos", "group_key": "cuotas", "default_value": null, "meter": "counter", "period": "month", "description": "Correos enviados por mes", "active": true, "sort": 70}, {"key": "module.commands", "kind": "flag", "unit": null, "group_key": "modulos", "default_value": 1, "meter": "none", "period": null, "description": "Comandos de chat", "active": true, "sort": 100}, {"key": "module.timers", "kind": "flag", "unit": null, "group_key": "modulos", "default_value": 1, "meter": "none", "period": null, "description": "Timers de mensajes", "active": true, "sort": 110}, {"key": "module.moderation", "kind": "flag", "unit": null, "group_key": "modulos", "default_value": 1, "meter": "none", "period": null, "description": "Moderacion basica", "active": true, "sort": 120}, {"key": "module.song_request", "kind": "flag", "unit": null, "group_key": "modulos", "default_value": 0, "meter": "none", "period": null, "description": "Song Request", "active": true, "sort": 130}, {"key": "module.giveaways", "kind": "flag", "unit": null, "group_key": "modulos", "default_value": 0, "meter": "none", "period": null, "description": "Sorteos", "active": true, "sort": 140}, {"key": "module.roulette", "kind": "flag", "unit": null, "group_key": "modulos", "default_value": 0, "meter": "none", "period": null, "description": "Ruleta", "active": true, "sort": 150}, {"key": "module.overlays", "kind": "flag", "unit": null, "group_key": "modulos", "default_value": 0, "meter": "none", "period": null, "description": "Overlays (chat, shoutout, Now Playing, alertas)", "active": true, "sort": 160}, {"key": "module.clips", "kind": "flag", "unit": null, "group_key": "modulos", "default_value": 0, "meter": "none", "period": null, "description": "Clips", "active": true, "sort": 170}, {"key": "module.live_translation", "kind": "flag", "unit": null, "group_key": "modulos", "default_value": 0, "meter": "none", "period": null, "description": "Traduccion en vivo", "active": true, "sort": 180}, {"key": "module.spirits", "kind": "flag", "unit": null, "group_key": "modulos", "default_value": 0, "meter": "none", "period": null, "description": "Spirits", "active": true, "sort": 190}, {"key": "module.tournaments", "kind": "flag", "unit": null, "group_key": "modulos", "default_value": 0, "meter": "none", "period": null, "description": "Torneos", "active": true, "sort": 200}, {"key": "module.tts", "kind": "flag", "unit": null, "group_key": "modulos", "default_value": 0, "meter": "none", "period": null, "description": "Texto a voz", "active": true, "sort": 210}, {"key": "module.multiview", "kind": "flag", "unit": null, "group_key": "modulos", "default_value": 0, "meter": "none", "period": null, "description": "Multi-view", "active": true, "sort": 220}, {"key": "module.pets", "kind": "flag", "unit": null, "group_key": "modulos", "default_value": 0, "meter": "none", "period": null, "description": "Mascotas", "active": true, "sort": 230}, {"key": "module.lol_coach", "kind": "flag", "unit": null, "group_key": "modulos", "default_value": 0, "meter": "none", "period": null, "description": "Coach de LoL", "active": true, "sort": 240}, {"key": "module.game_overlays", "kind": "flag", "unit": null, "group_key": "modulos", "default_value": 0, "meter": "none", "period": null, "description": "Game Overlays", "active": true, "sort": 250}, {"key": "module.discord", "kind": "flag", "unit": null, "group_key": "modulos", "default_value": 0, "meter": "none", "period": null, "description": "Bot de Discord (niveles, alertas, tienda)", "active": true, "sort": 260}, {"key": "byo.ai", "kind": "flag", "unit": null, "group_key": "byo", "default_value": 1, "meter": "none", "period": null, "description": "Permite cargar una llave propia de IA (sin llave, la funcion queda apagada)", "active": true, "sort": 300}, {"key": "byo.tts", "kind": "flag", "unit": null, "group_key": "byo", "default_value": 1, "meter": "none", "period": null, "description": "Llave propia de texto a voz", "active": true, "sort": 310}, {"key": "byo.stt", "kind": "flag", "unit": null, "group_key": "byo", "default_value": 1, "meter": "none", "period": null, "description": "Llave propia de voz a texto", "active": true, "sort": 320}, {"key": "byo.translate", "kind": "flag", "unit": null, "group_key": "byo", "default_value": 1, "meter": "none", "period": null, "description": "Llave propia de traduccion", "active": true, "sort": 330}, {"key": "feature.no_watermark", "kind": "flag", "unit": null, "group_key": "plataforma", "default_value": 0, "meter": "none", "period": null, "description": "Sin marca de agua", "active": true, "sort": 400}, {"key": "feature.subdomain", "kind": "flag", "unit": null, "group_key": "plataforma", "default_value": 0, "meter": "none", "period": null, "description": "Subdominio propio en decatron.top", "active": true, "sort": 410}, {"key": "feature.custom_domain", "kind": "flag", "unit": null, "group_key": "plataforma", "default_value": 0, "meter": "none", "period": null, "description": "Dominio propio del cliente", "active": true, "sort": 420}, {"key": "feature.api_v1", "kind": "flag", "unit": null, "group_key": "plataforma", "default_value": 0, "meter": "none", "period": null, "description": "API publica /v1", "active": true, "sort": 430}, {"key": "feature.priority_support", "kind": "flag", "unit": null, "group_key": "plataforma", "default_value": 0, "meter": "none", "period": null, "description": "Soporte prioritario", "active": true, "sort": 440}]$j$::json) ON CONFLICT (key) DO NOTHING;

INSERT INTO plans (key, name, sort, is_public, is_internal) VALUES ('internal', 'Interno (Decatron)', 0, false, true) ON CONFLICT (key) DO NOTHING;

INSERT INTO plan_entitlements (plan_id, capability_key, value)
SELECT p.id, e.capability_key, e.value FROM plans p, json_to_recordset($j$[{"capability_key": "byo.ai", "value": 1}, {"capability_key": "byo.stt", "value": 1}, {"capability_key": "byo.translate", "value": 1}, {"capability_key": "byo.tts", "value": 1}, {"capability_key": "feature.api_v1", "value": 1}, {"capability_key": "feature.custom_domain", "value": 1}, {"capability_key": "feature.no_watermark", "value": 1}, {"capability_key": "feature.priority_support", "value": 1}, {"capability_key": "feature.subdomain", "value": 1}, {"capability_key": "module.clips", "value": 1}, {"capability_key": "module.commands", "value": 1}, {"capability_key": "module.discord", "value": 1}, {"capability_key": "module.game_overlays", "value": 1}, {"capability_key": "module.giveaways", "value": 1}, {"capability_key": "module.live_translation", "value": 1}, {"capability_key": "module.lol_coach", "value": 1}, {"capability_key": "module.moderation", "value": 1}, {"capability_key": "module.multiview", "value": 1}, {"capability_key": "module.overlays", "value": 1}, {"capability_key": "module.pets", "value": 1}, {"capability_key": "module.roulette", "value": 1}, {"capability_key": "module.song_request", "value": 1}, {"capability_key": "module.spirits", "value": 1}, {"capability_key": "module.timers", "value": 1}, {"capability_key": "module.tournaments", "value": 1}, {"capability_key": "module.tts", "value": 1}, {"capability_key": "quota.admins", "value": null}, {"capability_key": "quota.channels", "value": null}, {"capability_key": "quota.chat_messages_month", "value": null}, {"capability_key": "quota.commands", "value": null}, {"capability_key": "quota.emails_month", "value": null}, {"capability_key": "quota.storage_mb", "value": null}, {"capability_key": "quota.timers", "value": null}]$j$::json) AS e(capability_key text, value numeric)
WHERE p.key = 'internal' ON CONFLICT DO NOTHING;

INSERT INTO tenant_subscriptions (tenant_id, plan_id, status)
SELECT 1, p.id, 'active' FROM plans p WHERE p.key = 'internal'
  AND NOT EXISTS (SELECT 1 FROM tenant_subscriptions s WHERE s.tenant_id = 1 AND s.status <> 'cancelled');
COMMIT;
